import React, { Component } from 'react'
import {Dimensions, Image, Text, TouchableWithoutFeedback, View, ScrollView, TouchableNativeFeedback, BackHandler} from 'react-native'
import styles from './challengeStyles';
import SnapCarousel from 'react-native-snap-carousel';
import axios from "axios/index";
const screen = Dimensions.get('window');
import {NavigationActions} from 'react-navigation';


class subject extends Component {

  static navigationOptions = ({ navigation }) => ({
    title: 'Select Topic',
    header: null
  })

   constructor() {
    super();
    this.state = {
      subjectName: [
        'Physics',
        'Chemistry',
        'Mathematics',
        'Science'
      ],
      subjects: [],
      subjectsBg: [
      {
        name: 'Physics',
        photo: 'data:image/png;base64,',
      },
      {
        name: 'Chemistry',
        photo: 'data:image/png;base64,',
      },
      {
        name: 'Mathematics',
        photo: 'data:image/png;base64,',
      },
      {
        name: 'Science',
        photo: 'data:image/png;base64,',
      }
      ],
      subjectsIcon: [
      {
        name: 'Physics',
        photo: 'data:image/png;base64,',
      },
      {
        name: 'Chemistry',
        photo: 'data:image/png;base64,',
      },
      {
        name: 'Mathematics',
        photo: 'data:image/png;base64,',
      },
      {
        name: 'Science',
        photo: 'data:image/png;base64,',
      }
      ],
      selectedSubject: null,
      selectedSubjectName: '',
      isReady: false
    }
    this.handleBackButton = this.handleBackButton.bind(this);
  }

  handleBackButton() {
    
    this.props.navigation.navigate('test1');
    return true;
  }

  componentWillUnmount() {
    BackHandler.removeEventListener('hardwareBackPress', this.handleBackButton);
  }

  async componentDidMount() {
    BackHandler.addEventListener('hardwareBackPress', this.handleBackButton);
    axios.get('https://classcast-198812.appspot.com/coursedata/testGoalAndSubjectList')
      .then((response) => {
        this.setState({subjects: response.data.subjects});
        this.setState({ selectedSubject: response.data.subjects[0]['index'],
                        selectedSubjectName: response.data.subjects[0]['name']
         });
        this.setState({isReady: true})
    })
  }

   render() {
    let {subjectsBg, subjectsIcon} = this.state;

    return (
      <View style={styles.container}>
        <View style={styles.topNav}>
          <Text style={styles.topNavTitle}>Create Challenge</Text>
          
        </View>
        <ScrollView
          style={styles.subjectCardsScrollContainer}
          contentContainerStyle={styles.subjectCardsContainer}
        >
          { this.state.isReady &&
            this.state.subjects.map((subject, index) => {
              console.log("sakjsab: "+JSON.stringify(this.state.subjects));
              return (
                <TouchableNativeFeedback
                  key={'subjectCards' + index}
                  onPress={() => {
                    //this.setState({selectedSubject: subject});
                    const navigateAction = NavigationActions.navigate({
                    routeName: 'chapter',
                    params: {
                     subject: this.state.subjects[index].name,
                     username: this.props.navigation.state.params.username,
                     name: this.props.navigation.state.params.name
                    },
                  });
                  this.props.navigation.dispatch(navigateAction);
                  }}
                >
                  <View
                    style={styles.subjectCard}
                  >
                    <Image
                      style={styles.subjectCardBackground}
                      source={{uri: this.state.subjectsBg[subject.index].photo}}
                    />
                    <Image
                      style={styles.subjectCardIcon}
                      source={{uri: this.state.subjectsIcon[subject.index].photo}}
                    />
                    <View style={styles.subjectInfo}>
                      <Text style={styles.subjectName}>{this.state.subjects[index].name}</Text>
                      <Text style={styles.subjectName}></Text>
                    </View>
                  </View>
                </TouchableNativeFeedback>
              )
            })
          }
        </ScrollView>
      </View>
    )
  }
}

export default subject
